size_t group_ind = min_bit / BITMAP_GROUP_NBITS;
size_t bit_ind = min_bit % BITMAP_GROUP_NBITS;
size_t nbits = binfo->nbits;
while (group_ind < BITMAP_GROUPS(nbits)) {
    bitmap_t group = bitmap[group_ind];
    if (group == ~(bitmap_t)0) {
        group_ind++;
        continue;
    }
    unsigned long mask = ~(bitmap_t)0 << bit_ind;
    if ((group & mask) == mask) {
        bit_ind += BITMAP_GROUP_NBITS - bit_ind;
        group_ind++;
        continue;
    }
    size_t bit = group_ind * BITMAP_GROUP_NBITS + ffs_lu(group & mask);
    if (bit < nbits) {
        return bit;
    }
    group_ind++;
}
return nbits;

